package cn.community.parkingservice;

import cn.community.foundation.*;
import jakarta.servlet.http.HttpServletRequest;
import java.time.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;

@RestController @Profile("business")
public class ResourceManagement {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final BusinessClock clock;
 private static final String ACTIVE="(status IN ('CONFIRMED','IN_USE') OR (status='WAIT_PAY' AND pay_deadline>?))";
 public ResourceManagement(JdbcTemplate db,PlatformTransactionManager manager,BusinessClock clock){this.db=db;tx=new TransactionTemplate(manager);this.clock=clock;}
 private Map<String,Object> one(String sql,Object...args){return Management.one(db,sql,args);}
 private Map<String,Object> community(long id){return one("SELECT * FROM community WHERE id=? FOR UPDATE",id);}
 private void available(Map<String,Object> c){Problem.require(Boolean.TRUE.equals(c.get("enabled")),409,"COMMUNITY_DISABLED","社区已停用");}
 private Map<String,Object> space(long id){var p=one("SELECT community_id FROM parking_space WHERE id=?",id);community(((Number)p.get("community_id")).longValue());return one("SELECT * FROM parking_space WHERE id=? FOR UPDATE",id);}
 private void own(Map<String,Object> p,Actor a){a.role("OWNER");Problem.require(((Number)p.get("owner_id")).longValue()==a.id(),404,"NOT_FOUND","记录不存在");}
 private void moderator(Map<String,Object> p,Actor a){if(a.roles().contains("PLATFORM"))a.permission("SPACE_MODERATE");else{a.permission("SPACE_REVIEW");Problem.require(a.communities().contains(((Number)p.get("community_id")).longValue()),403,"FORBIDDEN","无此社区审核权限");}}
 private void protectSpace(long id){Problem.require(db.queryForObject("SELECT COUNT(*) FROM reservation_order WHERE space_id=? AND "+ACTIVE,Integer.class,id,Data.ts(clock.now()))==0,409,"ACTIVE_RESERVATION","车位仍有关联有效预约");}
 private String plate(Map<String,Object> in){String plate=Management.text(in,"plate",20).replaceAll("\\s+","").toUpperCase(Locale.ROOT);Problem.require(plate.matches("[京津沪渝冀豫云辽黑湘皖鲁新苏浙赣鄂桂甘晋蒙陕吉闽贵粤青藏川宁琼][A-Z][A-Z0-9]{5,6}"),422,"INVALID_PLATE","请输入有效的普通或新能源车牌");return plate;}
 private String type(Map<String,Object> in){String type=Management.text(in,"spaceType",20);Problem.require(Set.of("STANDARD","COMPACT","EV").contains(type),422,"INVALID_SPACE_TYPE","车位类型无效");return type;}
 private long price(Map<String,Object> in){long value=Data.number(in,"hourlyFen");Problem.require(value>0&&value<=1000000,422,"INVALID_PRICE","小时价格须为1至1000000整数分");return value;}
 private Instant[] interval(Map<String,Object> in){Instant start=Instant.parse(Data.str(in,"startAt")),end=Instant.parse(Data.str(in,"endAt")),now=clock.now();Problem.require(start.getNano()==0&&end.getNano()==0&&start.getEpochSecond()%900==0&&end.getEpochSecond()%900==0,422,"TIME_ALIGNMENT","窗口按15分钟对齐");Problem.require(start.isAfter(now)&&end.isAfter(start)&&!end.isAfter(now.plus(Duration.ofDays(30))),422,"INVALID_INTERVAL","窗口必须位于未来30天且结束晚于开始");return new Instant[]{start,end};}
 @GetMapping("/internal/v1/communities/{id}") public Map<String,Object> internalCommunity(@PathVariable long id){return Data.row(one("SELECT id,name,enabled FROM community WHERE id=?",id));}
 @GetMapping("/api/v1/property/communities") public List<?> propertyCommunities(HttpServletRequest req){Actor a=Actor.of(req);a.permission("PARKING_OPERATE");return db.queryForList("SELECT id,name,address,enabled FROM community ORDER BY id").stream().filter(c->a.roles().contains("PLATFORM")||a.communities().contains(((Number)c.get("id")).longValue())).map(Data::row).toList();}
 @GetMapping("/api/v1/admin/communities") public Map<String,Object> communities(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor.of(req).permission("COMMUNITY_MANAGE");return Management.page(db,"id,name,address,enabled,version","FROM community","id",page,size);}
 @PostMapping("/api/v1/communities") public Map<String,Object> createCommunity(@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);a.permission("COMMUNITY_MANAGE");String name=Management.text(in,"name",100),address=Management.text(in,"address",255);return tx.execute(s->{long id=Data.id(db);db.update("INSERT INTO community(id,name,address) VALUES(?,?,?)",id,name,address);Management.audit(db,a,"COMMUNITY_CREATE",id,Map.of());return Data.row(one("SELECT * FROM community WHERE id=?",id));});}
 @PatchMapping("/api/v1/communities/{id}") public Map<String,Object> editCommunity(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);a.permission("COMMUNITY_MANAGE");return tx.execute(s->{var row=community(id);Management.version(in,row);String name=in.containsKey("name")?Management.text(in,"name",100):row.get("name").toString(),address=in.containsKey("address")?Management.text(in,"address",255):row.get("address").toString();boolean enabled=in.containsKey("enabled")?Management.enabled(in):Boolean.TRUE.equals(row.get("enabled"));db.update("UPDATE community SET name=?,address=?,enabled=?,version=version+1 WHERE id=?",name,address,enabled,id);Management.audit(db,a,"COMMUNITY_EDIT",id,Map.of("enabled",enabled));return Data.row(one("SELECT * FROM community WHERE id=?",id));});}
 @GetMapping("/api/v1/manage/vehicles") public Map<String,Object> vehicles(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor a=Actor.of(req);a.role("DRIVER");return Management.page(db,"id,plate,enabled,version","FROM vehicle WHERE user_id=?","id",page,size,a.id());}
 @PostMapping("/api/v1/vehicles") public Map<String,Object> createVehicle(@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);a.role("DRIVER");String plate=plate(in);return tx.execute(s->{long id=Data.id(db);db.update("INSERT INTO vehicle(id,user_id,plate) VALUES(?,?,?)",id,a.id(),plate);Management.audit(db,a,"VEHICLE_CREATE",id,Map.of());return Data.row(one("SELECT id,plate,enabled,version FROM vehicle WHERE id=?",id));});}
 @PatchMapping("/api/v1/vehicles/{id}") public Map<String,Object> editVehicle(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);a.role("DRIVER");return tx.execute(s->{var row=one("SELECT * FROM vehicle WHERE id=? AND user_id=? FOR UPDATE",id,a.id());Management.version(in,row);Problem.require(db.queryForObject("SELECT COUNT(*) FROM reservation_order WHERE vehicle_id=? AND "+ACTIVE,Integer.class,id,Data.ts(clock.now()))==0,409,"ACTIVE_RESERVATION","有效预约期间不能修改或停用车辆");String plate=in.containsKey("plate")?plate(in):row.get("plate").toString();boolean enabled=in.containsKey("enabled")?Management.enabled(in):Boolean.TRUE.equals(row.get("enabled"));db.update("UPDATE vehicle SET plate=?,enabled=?,version=version+1 WHERE id=?",plate,enabled,id);Management.audit(db,a,"VEHICLE_EDIT",id,Map.of("enabled",enabled));return Data.row(one("SELECT id,plate,enabled,version FROM vehicle WHERE id=?",id));});}
 @GetMapping("/api/v1/owner/spaces") public Map<String,Object> ownerSpaces(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor a=Actor.of(req);a.role("OWNER");return Management.page(db,"id,community_id,name,space_code,location_desc,space_type,proof_text,review_status,review_comment,enabled,version","FROM parking_space WHERE owner_id=?","id DESC",page,size,a.id());}
 @PostMapping("/api/v1/spaces") public Map<String,Object> createSpace(@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);a.role("OWNER");long community=Data.number(in,"communityId");String code=Management.text(in,"spaceCode",60),location=Management.text(in,"locationDesc",255),proof=Management.text(in,"proofText",1000),type=type(in);return tx.execute(s->{available(community(community));long id=Data.id(db);db.update("INSERT INTO parking_space(id,community_id,owner_id,name,space_code,location_desc,space_type,proof_text,hourly_fen) VALUES(?,?,?,?,?,?,?,?,1)",id,community,a.id(),code,code,location,type,proof);Management.audit(db,a,"SPACE_CREATE",id,Map.of());return Data.row(one("SELECT * FROM parking_space WHERE id=?",id));});}
 @PatchMapping("/api/v1/spaces/{id}") public Map<String,Object> editSpace(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);return tx.execute(s->{var row=space(id);own(row,a);Management.version(in,row);available(community(((Number)row.get("community_id")).longValue()));Problem.require(!row.get("review_status").equals("PENDING"),409,"REVIEW_PENDING","审核期间不能修改");protectSpace(id);db.update("UPDATE parking_space SET name=?,space_code=?,location_desc=?,space_type=?,proof_text=?,review_status='DRAFT',review_comment='',version=version+1 WHERE id=?",Management.text(in,"spaceCode",60),Management.text(in,"spaceCode",60),Management.text(in,"locationDesc",255),type(in),Management.text(in,"proofText",1000),id);Management.audit(db,a,"SPACE_EDIT",id,Map.of());return Data.row(one("SELECT * FROM parking_space WHERE id=?",id));});}
 @PostMapping("/api/v1/spaces/{id}/submit") public Map<String,Object> submit(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);return tx.execute(s->{var row=space(id);own(row,a);Management.version(in,row);available(community(((Number)row.get("community_id")).longValue()));Problem.require(Set.of("DRAFT","REJECTED").contains(row.get("review_status")),409,"INVALID_STATE","仅草稿或驳回车位可提交");db.update("UPDATE parking_space SET review_status='PENDING',version=version+1 WHERE id=?",id);Management.audit(db,a,"SPACE_SUBMIT",id,Map.of());return Data.row(one("SELECT * FROM parking_space WHERE id=?",id));});}
 @GetMapping("/api/v1/property/spaces") public Map<String,Object> reviews(@RequestParam long communityId,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor a=Actor.of(req);a.community(communityId);if(a.roles().contains("PLATFORM"))a.permission("SPACE_MODERATE");else a.permission("SPACE_REVIEW");return Management.page(db,"id,community_id,name,space_code,location_desc,space_type,proof_text,review_status,review_comment,enabled,version","FROM parking_space WHERE community_id=?","id DESC",page,size,communityId);}
 @PostMapping("/api/v1/spaces/{id}/reviews") public Map<String,Object> review(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);String decision=Data.str(in,"decision"),comment=Management.text(in,"comment",500);Problem.require(Set.of("APPROVE","REJECT").contains(decision),422,"INVALID_ARGUMENT","审核动作无效");return tx.execute(s->{var row=space(id);moderator(row,a);Management.version(in,row);Problem.require(row.get("review_status").equals("PENDING"),409,"INVALID_STATE","仅待审核车位可审核");db.update("UPDATE parking_space SET review_status=?,review_comment=?,version=version+1 WHERE id=?",decision.equals("APPROVE")?"APPROVED":"REJECTED",comment,id);db.update("INSERT INTO space_review(id,space_id,actor_id,decision,comment) VALUES(?,?,?,?,?)",Data.id(db),id,a.id(),decision,comment);Management.audit(db,a,"SPACE_REVIEW",id,Map.of("decision",decision,"comment",comment));return Data.row(one("SELECT * FROM parking_space WHERE id=?",id));});}
 @PatchMapping("/api/v1/spaces/{id}/status") public Map<String,Object> spaceStatus(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);boolean enabled=Management.enabled(in);String reason=Management.text(in,"reason",500);return tx.execute(s->{var row=space(id);moderator(row,a);Management.version(in,row);db.update("UPDATE parking_space SET enabled=?,version=version+1 WHERE id=?",enabled,id);Management.audit(db,a,"SPACE_STATUS",id,Map.of("enabled",enabled,"reason",reason));return Data.row(one("SELECT * FROM parking_space WHERE id=?",id));});}
 @GetMapping("/api/v1/spaces/{id}/windows") public Map<String,Object> windows(@PathVariable long id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor a=Actor.of(req);own(one("SELECT owner_id FROM parking_space WHERE id=?",id),a);return Management.page(db,"id,space_id,start_at,end_at,hourly_fen,enabled,version","FROM share_window WHERE space_id=?","start_at,id",page,size,id);}
 private void overlap(long spaceId,long exclude,Instant start,Instant end){Problem.require(db.queryForObject("SELECT COUNT(*) FROM share_window WHERE space_id=? AND id<>? AND enabled=TRUE AND start_at<? AND end_at>?",Integer.class,spaceId,exclude,Data.ts(end),Data.ts(start))==0,409,"WINDOW_OVERLAP","共享窗口不能重叠，相邻窗口允许");}
 @PostMapping("/api/v1/spaces/{id}/windows") public Map<String,Object> createWindow(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);return tx.execute(s->{var row=space(id);own(row,a);available(community(((Number)row.get("community_id")).longValue()));Problem.require(row.get("review_status").equals("APPROVED")&&Boolean.TRUE.equals(row.get("enabled")),409,"SPACE_UNAVAILABLE","车位须审核通过且启用");var times=interval(in);long price=price(in);overlap(id,-1,times[0],times[1]);long windowId=Data.id(db);db.update("INSERT INTO share_window(id,space_id,start_at,end_at,hourly_fen) VALUES(?,?,?,?,?)",windowId,id,Data.ts(times[0]),Data.ts(times[1]),price);Management.audit(db,a,"WINDOW_CREATE",windowId,Map.of("spaceId",Long.toString(id),"hourlyFen",price));return Data.row(one("SELECT * FROM share_window WHERE id=?",windowId));});}
 @PatchMapping("/api/v1/windows/{id}") public Map<String,Object> editWindow(@PathVariable long id,@RequestBody Map<String,Object> in,HttpServletRequest req){Actor a=Actor.of(req);return tx.execute(s->{long spaceId=((Number)one("SELECT space_id FROM share_window WHERE id=?",id).get("space_id")).longValue();var p=space(spaceId);own(p,a);var row=one("SELECT * FROM share_window WHERE id=? FOR UPDATE",id);Management.version(in,row);
  Problem.require(db.queryForObject("SELECT COUNT(*) FROM reservation_order WHERE space_id=? AND "+ACTIVE+" AND (window_id=? OR (window_id IS NULL AND start_at<? AND end_at>?))",Integer.class,spaceId,Data.ts(clock.now()),id,row.get("end_at"),row.get("start_at"))==0,409,"ACTIVE_RESERVATION","窗口有有效预约，不能修改或停用");
  boolean enabled=in.containsKey("enabled")?Management.enabled(in):Boolean.TRUE.equals(row.get("enabled"));
  Instant start=Data.instant(row.get("start_at")),end=Data.instant(row.get("end_at"));long price=((Number)row.get("hourly_fen")).longValue();
  if(in.containsKey("startAt")||in.containsKey("endAt")||in.containsKey("hourlyFen")){var times=interval(in);start=times[0];end=times[1];price=price(in);}
  if(enabled){available(community(((Number)p.get("community_id")).longValue()));Problem.require(p.get("review_status").equals("APPROVED")&&Boolean.TRUE.equals(p.get("enabled")),409,"SPACE_UNAVAILABLE","车位不可用");Problem.require(start.isAfter(clock.now())&&!end.isAfter(clock.now().plus(Duration.ofDays(30))),409,"WINDOW_EXPIRED","只能维护未来30天窗口");overlap(spaceId,id,start,end);}
  db.update("UPDATE share_window SET start_at=?,end_at=?,hourly_fen=?,enabled=?,version=version+1 WHERE id=?",Data.ts(start),Data.ts(end),price,enabled,id);Management.audit(db,a,"WINDOW_EDIT",id,Map.of("enabled",enabled,"hourlyFen",price));return Data.row(one("SELECT * FROM share_window WHERE id=?",id));});}
 @GetMapping("/api/v1/admin/audit-logs/parking") public Map<String,Object> audit(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,HttpServletRequest req){Actor.of(req).permission("AUDIT_READ");return Management.page(db,"id,actor_id,action,resource_id,created_at,detail_json","FROM audit_log","id DESC",page,size);}
}
